SQL_DOC.P_SQL:
SELECT 'BNG' AS PLANT, SUBSTR(B.REF_PR_NO, INSTR(B.REF_PR_NO,'-',-1,1)+1) AS REQUNO, NVL(A.INV_NO ,' ') AS INVOICE_NO, TO_NUMBER(A.INV_SEQ) AS INVOICE_SEQ, NVL(B.REF_IF_NO ,' ') AS BUYER_ITEM_NO, NVL(A.STATUS ,' ') AS STATUS, REPLACE(REPLACE(REPLACE(REPLACE(B.LEGACY_PO_NO,'PR-',''),'PO-',''),'-C',''),'-K','') AS LEGACY_PO_NO, TO_NUMBER(B.LEGACY_PO_SEQ) AS LEGACY_PO_SEQ, NVL(B.PO_NO ,' ') AS PURCHASE_NO, NVL(A.INVOICE_DATE ,' ') AS ADD_DATE, NVL(B.UNIT_PRICE , 0 ) AS UNIT_PRICE, NVL(A.INV_QTY , 0 ) AS ITEM_QTY, NVL(B.UNIT_PRICE*A.INV_QTY , 0 ) AS ITEM_AMT, SUBSTR(B.REF_PR_NO, 0, INSTR(B.REF_PR_NO,'-',1,1)-1) AS LEGACY_PR_NO , D.REMARK_INV AS REMARK , CASE WHEN B.LEGACY_PO_NO LIKE 'PR-%' THEN 'Y' ELSE 'N' END AS ADVANCE_FLAG , 'N' AS DELIV_YN, ' ' AS DELIV_DATE, ' ' AS DELIV_NAME, ' ' AS DELIV_TEL FROM ICOMIVDT A, ICOMPODT B, ICOMTRXL C, ICOMIVHD D WHERE A.BUYER = C.TARGET AND A.INV_NO = C.KEY_1 AND A.INV_SEQ = C.KEY_2 AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND A.BUYER = D.BUYER AND A.INV_NO = D.INV_NO AND B.STATUS != 'D' AND C.DOC_NAME = 'IVDOWN' AND C.TARGET = '$G_RS.BUYER$' AND C.KEY_1 = '$G_RS.INV_NO$' AND C.KEY_2 = '$G_RS.INV_SEQ$' AND TRIM(C.KEY_9) IS NULL AND B.PROCESS_TYPE = '0'
UNION ALL
SELECT 'BNG' AS PLANT, SUBSTR(B.REF_PR_NO, INSTR(B.REF_PR_NO,'-',-1,1)+1) AS REQUNO, NVL(E.INV_NO ,' ') AS INVOICE_NO, TO_NUMBER(E.INV_SEQ) AS INVOICE_SEQ, NVL(B.REF_IF_NO ,' ') AS BUYER_ITEM_NO, NVL(E.STATUS ,' ') AS STATUS, REPLACE(REPLACE(REPLACE(REPLACE(B.LEGACY_PO_NO,'PR-',''),'PO-',''),'-C',''),'-K','') AS LEGACY_PO_NO, TO_NUMBER(B.LEGACY_PO_SEQ) AS LEGACY_PO_SEQ, NVL(B.PO_NO ,' ') AS PURCHASE_NO, NVL(E.INV_DATE ,' ') AS ADD_DATE, NVL(B.UNIT_PRICE , 0 ) AS UNIT_PRICE, NVL(E.INV_QTY , 0 ) AS ITEM_QTY, NVL(B.UNIT_PRICE*A.INV_QTY , 0 ) AS ITEM_AMT, SUBSTR(B.REF_PR_NO, 0, INSTR(B.REF_PR_NO,'-',1,1)-1) AS LEGACY_PR_NO , D.REMARK_INV AS REMARK , CASE WHEN B.LEGACY_PO_NO LIKE 'PR-%' THEN 'Y' ELSE 'N' END AS ADVANCE_FLAG , CASE WHEN E.S_INV_NO IS NOT NULL THEN 'Y' ELSE 'N' END AS DELIV_YN, CASE WHEN E.S_INV_NO IS NOT NULL THEN TO_CHAR(SYSDATE, 'YYYYMMDD') ELSE ' ' END AS DELIV_DATE, NVL( (SELECT TEXT2 FROM ICOMCOD1 T WHERE T.CODE = E.DELIVERY_PERSON AND T.TYPE = 'C014') ,' ') AS DELIV_NAME, NVL( (SELECT TEXT3 FROM ICOMCOD1 T WHERE T.CODE = E.DELIVERY_PERSON AND T.TYPE = 'C014') ,' ') AS DELIV_TEL FROM ICOMIVDT A, ICOMPODT B, ICOMTRXL C, ICOMIVHD D, WMSIVDT E WHERE E.BUYER = C.TARGET AND E.INV_NO = C.KEY_1 AND E.INV_SEQ = C.KEY_2 AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND A.BUYER = D.BUYER AND A.INV_NO = D.INV_NO AND B.STATUS != 'D'
AND A.BUYER = E.BUYER AND A.PO_NO = E.PO_NO AND A.PO_SEQ = E.PO_SEQ AND A.INV_NO = E.S_INV_NO AND A.INV_SEQ = E.S_INV_SEQ
AND C.DOC_NAME = 'IVDOWN' AND C.TARGET = '$G_RS.BUYER$' AND C.KEY_1 = '$G_RS.INV_NO$' AND C.KEY_2 = '$G_RS.INV_SEQ$' AND TRIM(C.KEY_9) IS NULL AND B.PROCESS_TYPE != '0'
DECLARE
V_COUNT NUMBER; V_SEND_DATE ICOMIVDT.SEND_DATE%TYPE; V_SEND_TIME ICOMIVDT.SEND_TIME%TYPE; V_SEND_DATETIME ICOMTRXL.KEY_8%TYPE;
BEGIN
SELECT TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') INTO V_SEND_DATE, V_SEND_TIME, V_SEND_DATETIME FROM DUAL;
V_COUNT := 0;
SELECT COUNT(1) INTO V_COUNT FROM ICOMIVDT WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ = '$G_RS.INV_SEQ$' AND TRIM(SEND_DATE) IS NULL AND ROWNUM = 1 ;
IF V_COUNT = 1 THEN
UPDATE ICOMIVDT SET SEND_DATE = V_SEND_DATE, SEND_TIME = V_SEND_TIME WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ = '$G_RS.INV_SEQ$' AND TRIM(SEND_DATE) IS NULL ;
END IF;
V_COUNT := 0;
SELECT COUNT(1) INTO V_COUNT FROM WMSIVDT WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ = '$G_RS.INV_SEQ$' AND TRIM(SEND_DATE) IS NULL AND ROWNUM = 1 ;
IF V_COUNT = 1 THEN
UPDATE WMSIVDT SET SEND_DATE = V_SEND_DATE, SEND_TIME = V_SEND_TIME WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ = '$G_RS.INV_SEQ$' AND TRIM(SEND_DATE) IS NULL ;
END IF;
DELETE FROM ICOMTRXL WHERE DOC_NAME = 'IVDOWN' AND TARGET = '$G_RS.BUYER$' AND KEY_1 = '$G_RS.INV_NO$' AND KEY_2 = '$G_RS.INV_SEQ$' AND TRIM(KEY_9) IS NULL ;
DELETE FROM ICOMTRXL C WHERE DOC_NAME = 'IVDOWN' AND TRIM(KEY_9) IS NULL AND TARGET IN ('KRXPR00948') AND NOT EXISTS ( SELECT 'X' FROM ICOMIVDT A, ICOMPODT B WHERE A.BUYER = C.TARGET AND A.INV_NO = C.KEY_1 AND A.INV_SEQ = C.KEY_2 AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ = B.PO_SEQ AND B.PROCESS_TYPE = '0' ) AND NOT EXISTS ( SELECT 'X' FROM WMSIVDT E, ICOMPODT B WHERE E.BUYER = C.TARGET AND E.INV_NO = C.KEY_1 AND E.INV_SEQ = C.KEY_2 AND E.BUYER = B.BUYER AND E.PO_NO = B.PO_NO AND E.PO_SEQ = B.PO_SEQ AND B.PROCESS_TYPE != '0' ) ;
END;
DELETE FROM ICOMTRXL WHERE DOC_NAME = 'IVDOWN' AND TARGET = '$G_RS.BUYER$' AND KEY_1 = '$G_RS.INV_NO$' AND KEY_2 = '$G_RS.INV_SEQ$' AND TRIM(KEY_9) IS NULL
